int _peer_receive_session_frame(int fd, unsigned char* dst, size_t want) {
    size_t received = 0;
    while (received < want) {
        int rc;
        do {
            rc = _net_recv_data(fd, dst + received, want - received);
        } while (rc == -1 && (errno == EAGAIN || errno == EINTR));

        if (rc <= 0) {
            continue;
        }
        received += (size_t)rc;
    }
    return 0;
}

